125: function qualificationClockValid(p,at){
126:   const known=p.qualification_known_ts??p.created_ts;
127:   return validTime(known)&&validTime(p.created_ts)&&known>=p.created_ts&&known<=at&&
128:     Array.isArray(p.qualification)&&p.qualification.every(q=>validTime(q.end_ts)&&q.end_ts<=known);
129: }
130: function usablePrevious(p,input,profile) {
131:   return p&&p.instrument_id===input.instrument.instrument_id&&typeof p.wave_id==='string'&&validTime(p.created_ts)&&p.created_ts<=input.analysis_ts&&
132:     waveLifetimeValid(p,input.analysis_ts,profile)&&p.expires_ts>input.analysis_ts&&!['CANCELLED','EXPIRED'].includes(p.state)&&
133:     qualificationClockValid(p,input.analysis_ts)&&
134:     p.impulse&&positive(p.impulse.baseline_median)&&positive(p.impulse.normal_range)&&validTime(p.impulse.end_ts)&&p.impulse.end_ts<=p.created_ts;
135: }
136: export function analyzeMovement(input, rows, price, ticker, profile, observedDay=null) {
137:   const windows=growthWindows(rows,ticker,profile,observedDay).map(w=>{
138:     if(!positive(w.start_price)||!positive(w.end_price))return w;
139:     const fact=w.basis==='OBSERVED_CLOSED_OHLC_24H'?input.facts.growth_24h:w.fact_ids?.includes(ticker?.fact_id)?ticker:input.facts.candles;
140:     return {...w,fact_ids:w.fact_ids??[fact.fact_id],evidence_ref:w.evidence_ref??fact.evidence_ref??null,source:fact.source,source_event_ts:fact.event_ts};
141:   }),current_threshold_passed=windows.some(w=>w.passed),now=input.analysis_ts,end=rows.at(-1)?.close_ts;
142:   const p=input.previous_wave,previous=usablePrevious(p,input,profile)?p:null;
143:   const expired=p?.instrument_id===input.instrument.instrument_id&&validTime(p.expires_ts)&&p.expires_ts<=now;
144:   const candidates=[];
145:   for(const row of rows){if(row.close_ts<end-profile.wave_search_ms)continue;const v=volumeComparison(rows,row.close_ts,profile,input);
146:     if(v&&v.ratio!==null&&v.ratio>=profile.elevated_volume_ratio&&v.return_pct>0)candidates.push(v);}
147:   // A retained impulse keeps its original baseline and lifetime.
148:   const terminal=p?.instrument_id===input.instrument.instrument_id&&['CANCELLED','EXPIRED'].includes(p.state);
149:   const postBreachCause=terminal&&!expired?provePostBreachCause(input,rows,profile):null;
150:   const postBreachSeed=selectPostBreachSeed(candidates,postBreachCause,rows,price,now,profile);
151:   const terminalTs=expired||terminal&&p.state==='EXPIRED'?p.expires_ts:postBreachCause?.terminal_event_ts??(terminal?(p.cancelled_ts??p.expires_ts):null);
152:   const eligibleCandidates=terminalTs===null?candidates:candidates.filter(v=>v.start_ts>=terminalTs);
153:   // First observation prefers the earliest intact initial seed as of now.
154:   // If none is intact, retain the original selector and cold-base path.
155:   const initialImpulse=p===null?eligibleCandidates.slice().sort((a,b)=>a.start_ts-b.start_ts||a.end_ts-b.end_ts)
156:     .find(v=>completeInterval(rows,v.start_ts,end)&&price>=v.low&&
157:       !rows.some(r=>r.open_ts>=v.end_ts&&r.low<v.low))??null:null;
158:   const impulse=postBreachCause?postBreachSeed:initialImpulse??previous?.impulse??eligibleCandidates.sort((a,b)=>b.ratio-a.ratio||a.end_ts-b.end_ts)[0]??null;

183:   const recent=windowRows(rows,end,profile.impulse_window_ms,profile.candle_interval_ms),field=impulse.field;
184:   const basis=recent?volumeBasis(recent,input,profile,field):null;
185:   if(basis&&!sameVolumeBasis(impulse,basis))return {...base,wave_id:previous?.wave_id??null,state:previous?.state??null,next_wave:previous?{...previous}:null,
186:     volume_basis:basis,reasons:['WAVE_VOLUME_COMPARISON_BASIS_CHANGED']};
187:   if(!positive(impulse.volume))return {...base,wave_id:previous?.wave_id??null,state:previous?.state??null,next_wave:previous?{...previous}:null,
188:     volume_basis:basis,current_to_impulse_volume_ratio:null,current_to_impulse_volume_ratio_reason:'IMPULSE_VOLUME_ZERO_OR_UNKNOWN',reasons:['IMPULSE_VOLUME_ZERO_OR_UNKNOWN']};
189:   const continuityStart=previous?.covered_until_ts??impulse.start_ts;
190:   if(!completeInterval(rows,continuityStart,end))return {...base,state:previous?.state??null,next_wave:previous?{...previous}:null,reasons:['WAVE_PATH_INCOMPLETE']};
191:   // PROTOTYPE: a verified first cold classification may use the first
192:   // confirmed post-breach base. A terminal permits only a distinct seed already
193:   // admitted by the existing post-terminal selector; the old wave is preserved.
194:   const originalInvalidation=previous?.invalidation_price??impulse.low;
195:   const originalCancel=price<originalInvalidation||rows.some(r=>r.open_ts>=Math.max(impulse.end_ts,continuityStart)&&r.low<originalInvalidation);
196:   let cold=null;
197:   if(!postBreachCause&&(p===null||terminal||expired)&&originalCancel){
198:     const seedWaveRows=rows.filter(r=>r.close_ts>=impulse.start_ts),seedPeak=Math.max(...seedWaveRows.map(r=>r.high));
199:     const seedPeakRow=seedWaveRows.find(r=>r.high===seedPeak);
200:     const seedLevels=pivots.filter(r=>r.known_ts<=seedPeakRow.close_ts&&r.price<seedPeak&&r.price>impulse.low).sort((a,b)=>b.price-a.price);
201:     const proposal=proposeColdStructuralBase({input,rows,pivots,impulse,price,reclaim_level:seedLevels[0]?.price??impulse.open,profile});
202:     if(proposal.status==='STRUCTURAL_CANDIDATE')cold=proposal.boundary;
203:   }
204:   const invalidation=cold?.invalidation_price??originalInvalidation;
205:   const invalidationStart=cold?.invalidation_observation_start??Math.max(impulse.end_ts,continuityStart);
206:   const observedCancel=cold?price<invalidation||rows.some(r=>r.open_ts>=invalidationStart&&r.low<invalidation):originalCancel;
207:   if(!observedCancel&&(!recent||!basis||!recent.every(r=>finite(r[field]))||!finite(sum(recent.map(r=>r[field])))||sum(recent.map(r=>r[field]))<=0))return {...base,state:previous?'WEAKENING':null,next_wave:previous?{...previous,state:'WEAKENING',covered_until_ts:end}:null,reasons:['CURRENT_VOLUME_REQUIRED']};
208:   let qualification=previous?.qualification??[],qualificationKnown=previous?.qualification_known_ts??(qualification.length?previous.created_ts:null);
209:   // The first observation can be a manual review below AUTO thresholds. Latch
210:   // the first later confirmed threshold once, without restarting this wave.
211:   if(!observedCancel&&qualification.length===0&&windows.some(w=>w.passed)){
212:     qualification=windows.filter(w=>w.passed).map(w=>({...w,fact_ids:w.fact_ids??facts}));qualificationKnown=now;
213:   }
214:   const qualified=validTime(qualificationKnown)&&qualificationKnown<=now&&qualification.some(w=>validTime(w.end_ts)&&w.end_ts<=qualificationKnown&&w.passed===true&&positive(w.start_price)&&positive(w.end_price)&&
215:     growthAtLeast(w.end_price,w.start_price,w.window_ms===86400000?profile.automatic_growth.day_pct:profile.automatic_growth.short_pct));

221:   const waveRows=rows.filter(r=>r.close_ts>=impulse.start_ts),peak=Math.max(previous?.peak_price??0,...waveRows.map(r=>r.high));
222:   const peakRow=waveRows.find(r=>r.high===peak)??{close_ts:previous.peak_event_ts},afterPeak=waveRows.filter(r=>r.close_ts>peakRow.close_ts);
223:   const fall=100*(1-price/peak),minutes=Math.max(1,(end-peakRow.close_ts)/60000),normalSpeed=(impulse.normal_range/peak*100)/(profile.impulse_window_ms/60000);
224:   const sharp=fall/minutes>normalSpeed*profile.sharp_speed_multiple||['SHARP_PULLBACK_UNCONFIRMED','SHARP_PULLBACK_RECLAIMED'].includes(previous?.state);
225:   const levels=pivots.filter(r=>r.known_ts<=peakRow.close_ts&&r.price<peak&&r.price>impulse.low).sort((a,b)=>b.price-a.price);
226:   const reclaim=previous?.reclaim_level??cold?.reclaim_level??levels[0]?.price??impulse.open;
227:   const breached=afterPeak.some(r=>r.low<reclaim)||previous?.reclaim_breached===true;
228:   const last=rows.slice(-profile.reclaim_closed_bars),returned=breached&&last.length===profile.reclaim_closed_bars&&last.every(r=>r.close>reclaim);
229:   const cancelled=observedCancel;
230:   let state=price>=peak?'ACTIVE_WAVE':sharp?(returned?'SHARP_PULLBACK_RECLAIMED':'SHARP_PULLBACK_UNCONFIRMED'):'CALM_PULLBACK';
231:   if(recent&&previous&&['CALM_PULLBACK','SHARP_PULLBACK_RECLAIMED'].includes(previous.state)&&recent.at(-1).close>recent[0].open&&sum(recent.map(r=>r[field]??0))>(previous.current_volume??Infinity))state='RESUMING';
232:   if(recent&&!sharp&&sum(recent.map(r=>r[field]??0))>=impulse.volume&&recent.at(-1).close<=recent[0].open)state='WEAKENING';
233:   if(cancelled)state='CANCELLED';
234:   const next_wave={wave_id,instrument_id:input.instrument.instrument_id,created_ts:created,expires_ts:(lifetimeAnchor??created)+profile.wave_max_age_ms,qualification,qualification_known_ts:qualificationKnown,
235:     ...(postBreachRearm?{lifetime_anchor_ts:lifetimeAnchor,post_breach_rearm:structuredClone(postBreachRearm)}:{}),
236:     impulse:{...impulse},state,reclaim_level:reclaim,reclaim_breached:breached,invalidation_price:invalidation,current_volume:recent?sum(recent.map(r=>r[field]??0)):null,
237:     covered_until_ts:end,peak_price:peak,peak_event_ts:peakRow.close_ts,confirmed_pivots:pivots,cancelled_ts:cancelled?now:null,
238:     ...((cold??previous?.cold_first_structural_base)?{cold_first_structural_base:structuredClone(cold??previous.cold_first_structural_base)}:{})};
239:   const currentRatio=positive(impulse.volume)&&finite(next_wave.current_volume/impulse.volume)?next_wave.current_volume/impulse.volume:null;
240:   return {...base,active:!cancelled,state,wave_id,automatic_eligible:qualified&&!cancelled,qualification,next_wave,peak_price:peak,reclaim_level:reclaim,
241:     volume_basis:basis,current_volume:next_wave.current_volume,current_to_impulse_volume_ratio:currentRatio,current_to_impulse_volume_ratio_reason:currentRatio===null?'CURRENT_TO_IMPULSE_RATIO_NOT_FINITE':null,
242:     current_to_impulse_volume_ratio_unit:'RATIO',reasons:cancelled?['PLAN_INVALIDATED']:[]};

8: export function waveLifetimeValid(wave,at,profile){
9:   if(!wave||!time(at)||!time(wave.created_ts)||wave.created_ts>at||!time(wave.expires_ts)||
10:     !Number.isSafeInteger(profile?.wave_max_age_ms)||profile.wave_max_age_ms<=0)return false;
11:   const anchored=Object.hasOwn(wave,'lifetime_anchor_ts'),proved=Object.hasOwn(wave,'post_breach_rearm');
12:   if(!anchored&&!proved)return wave.expires_ts===wave.created_ts+profile.wave_max_age_ms;
13:   if(!anchored||!proved)return false;
14:   const p=wave.post_breach_rearm,s=wave.impulse;
15:   return Boolean(time(wave.lifetime_anchor_ts)&&wave.lifetime_anchor_ts<=wave.created_ts&&
16:     wave.expires_ts===wave.lifetime_anchor_ts+profile.wave_max_age_ms&&
17:     p&&p.version===POST_BREACH_WAVE_VERSION&&text(wave.wave_id)&&text(p.prior_wave_id)&&p.prior_wave_id!==wave.wave_id&&
